package com.smartgrocery.controller; import com.smartgrocery.entity.Inventory; import com.smartgrocery.service.InventoryService; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.*; @RestController @RequestMapping("/api/v1/inventory") public class InventoryController {private final InventoryService service;public InventoryController(InventoryService s){service=s;} @GetMapping public List<Inventory> all(){return service.all();} @PostMapping("/{id}/adjust") public Inventory adjust(@PathVariable Long id,@RequestParam BigDecimal quantity){return service.adjust(id,quantity);} @PostMapping("/{id}/add") public Inventory add(@PathVariable Long id,@RequestParam BigDecimal quantity){return service.adjust(id,quantity);} @PostMapping("/{id}/remove") public Inventory remove(@PathVariable Long id,@RequestParam BigDecimal quantity){return service.adjust(id,quantity.negate());}}